                }

                setEditLoading(true)
                try {
                  const res = await fetch(`/api/admin/students/attendance/${editLog.id}`, {
                    method: "PATCH",
                    headers: { "Content-Type": "application/json" },
                    body: JSON.stringify({ status: editStatus }),
