import { prisma } from "@/lib/prisma"
import { auth, clerkClient } from "@clerk/nextjs/server"
import { NextResponse } from "next/server"

const attendanceModel = prisma.attendance as any
const userModel = prisma.user as any

function getNamePartsCount(value: string) {
  return value
    .trim()
    .split(/\s+/)
    .filter(Boolean).length
}

function pickFullerDisplayName(dbName: string | null | undefined, clerkName: string | undefined) {
  const normalizedDb = typeof dbName === "string" ? dbName.trim() : ""
  const normalizedClerk = typeof clerkName === "string" ? clerkName.trim() : ""

  if (!normalizedDb && !normalizedClerk) {
    return ""
  }
  if (!normalizedDb) {
    return normalizedClerk
  }
  if (!normalizedClerk) {
    return normalizedDb
  }

  return getNamePartsCount(normalizedDb) >= getNamePartsCount(normalizedClerk)
    ? normalizedDb
    : normalizedClerk
}

async function isAdmin(clerkUserId: string) {
  const actor = await prisma.user.findUnique({
    where: { clerkUserId },
    select: { role: true },
  })

  return actor?.role === "ADMIN"
}

export async function GET(req: Request) {
  const { userId } = await auth()

  if (!userId) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
  }

  if (!(await isAdmin(userId))) {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 })
  }

  const url = new URL(req.url)
  const studentId = url.searchParams.get("studentId")?.trim() ?? ""
  const department = url.searchParams.get("department")?.trim() ?? ""
  const yearRaw = url.searchParams.get("year")?.trim() ?? ""

  const year = Number(yearRaw)
  let typedLogs: Array<{
    id: string
    status: "PRESENT" | "ABSENT" | "EXCUSED"
    createdAt: Date
    session: {
      id: string
      subject: string
      department: string
      year: number
      createdBy: string
      createdAt: Date
      expiresAt: Date
    }
    student: {
      id: string
      fullName: string
      email: string | null
      department: string
      year: number
      rollNo: number
    }
  }>

  if (studentId) {
    // For a specific student, build a full history similar to the
    // student dashboard: every scheduled class for their
    // department/year, marked as PRESENT / EXCUSED / ABSENT.

    const student = await prisma.student.findUnique({
      where: { id: studentId },
      select: {
        id: true,
        fullName: true,
        email: true,
        department: true,
        year: true,
        rollNo: true,
        user: {
          select: {
            createdAt: true,
          },
        },
      },
    })

    if (!student) {
      return NextResponse.json({ error: "Student not found" }, { status: 404 })
    }

    const effectiveFrom = student.user?.createdAt ?? new Date(0)
    const now = new Date()

    const sessions = await prisma.session.findMany({
      where: {
        department: student.department,
        year: student.year,
        createdAt: { gte: effectiveFrom, lte: now },
      },
      orderBy: { createdAt: "desc" },
      take: 2000,
      select: {
        id: true,
        subject: true,
        department: true,
        year: true,
        createdBy: true,
        createdAt: true,
        expiresAt: true,
      },
    })

    if (sessions.length === 0) {
      return NextResponse.json({ count: 0, logs: [] })
    }

    const sessionIds = sessions.map((session) => session.id)

    const attendances = await attendanceModel.findMany({
      where: {
        studentId,
        sessionId: { in: sessionIds },
      },
      select: {
        id: true,
        status: true,
        createdAt: true,
        sessionId: true,
      },
    })

    const attendanceBySessionId = new Map<
      string,
      { id: string; status: "PRESENT" | "ABSENT" | "EXCUSED"; createdAt: Date; sessionId: string }
    >()

    for (const row of attendances as Array<{
      id: string
      status: "PRESENT" | "ABSENT" | "EXCUSED"
      createdAt: Date
      sessionId: string
    }>) {
      attendanceBySessionId.set(row.sessionId, row)
    }

    const studentInfo = {
      id: student.id,
      fullName: student.fullName,
      email: student.email,
      department: student.department,
      year: student.year,
      rollNo: student.rollNo,
    }

    typedLogs = sessions.map((session) => {
      const attendance = attendanceBySessionId.get(session.id)

      const status: "PRESENT" | "ABSENT" | "EXCUSED" =
        attendance?.status === "PRESENT"
          ? "PRESENT"
          : attendance?.status === "EXCUSED"
            ? "EXCUSED"
            : "ABSENT"

      return {
        id: attendance?.id ?? `${session.id}:${student.id}`,
        status,
        createdAt: session.createdAt,
        session,
        student: studentInfo,
      }
    })
  } else {
    // For all students: build full history like per-student view
    const now = new Date()
    const effectiveFrom = new Date(0) // Adjust if needed, e.g., academic year start

    let whereClause: any = {
      createdAt: { gte: effectiveFrom, lte: now },
    }

    if (department) {
      whereClause.department = { equals: department, mode: "insensitive" }
    }
    if (yearRaw && !Number.isNaN(year)) {
      whereClause.year = year
    }

    const sessions = await prisma.session.findMany({
      where: whereClause,
      orderBy: { createdAt: "desc" },
      take: 2000,
      select: {
        id: true,
        subject: true,
        department: true,
        year: true,
        createdBy: true,
        createdAt: true,
        expiresAt: true,
      },
    })

    if (sessions.length === 0) {
      return NextResponse.json({ count: 0, logs: [] })
    }

    const sessionIds = sessions.map((session) => session.id)

    // Get unique students relevant to these sessions' dept/year combos
    const sessionDeptsYears = [...new Set(sessions.map(s => `${s.department}-${s.year}`))]
    const relevantStudents = await prisma.student.findMany({
      where: {
        OR: [
          {
            isActive: true,
            OR: sessionDeptsYears.map(dy => {
              const [dept, y] = dy.split('-')
              return { department: { equals: dept, mode: "insensitive" }, year: Number(y) }
            }),
          },
          {
            attendances: {
              some: {
                sessionId: { in: sessionIds },
              },
            },
          },
        ],
      },
      select: {
        id: true,
        fullName: true,
        email: true,
        department: true,
        year: true,
        rollNo: true,
      },
    })

    // Fetch existing attendances for these sessions
    const attendances = await attendanceModel.findMany({
      where: {
        sessionId: { in: sessionIds },
      },
      select: {
        id: true,
        status: true,
        createdAt: true,
        sessionId: true,
        studentId: true,
      },
    })

    const attendanceBySessionStudent = new Map<string, { id: string; status: "PRESENT" | "ABSENT" | "EXCUSED"; createdAt: Date; sessionId: string; studentId: string }>()
    for (const row of attendances as any[]) {
      const key = `${row.sessionId}:${row.studentId}`
      attendanceBySessionStudent.set(key, row)
    }

    // Generate full logs
    const allCombos: Array<{
      session: typeof sessions[0]
      student: typeof relevantStudents[0]
    }> = []

    for (const session of sessions) {
      for (const student of relevantStudents.filter(s => s.department.toUpperCase() === session.department.toUpperCase() && s.year === session.year)) {
        allCombos.push({ session, student })
      }
    }

    typedLogs = allCombos.map(({ session, student }) => {
      const key = `${session.id}:${student.id}`
      const attendance = attendanceBySessionStudent.get(key)

      const status: "PRESENT" | "ABSENT" | "EXCUSED" =
        attendance?.status === "PRESENT"
          ? "PRESENT"
          : attendance?.status === "EXCUSED"
            ? "EXCUSED"
            : "ABSENT"

      return {
        id: attendance?.id ?? `${session.id}:${student.id}`,
        status,
        createdAt: session.createdAt,
        session,
        student,
      }
    })
  }

  const creatorIds = Array.from(new Set(typedLogs.map((log) => log.session.createdBy))) as string[]
  const creators =
    creatorIds.length > 0
      ? await userModel.findMany({
          where: { id: { in: creatorIds } },
          select: {
            id: true,
            clerkUserId: true,
            email: true,
            teacher: {
              select: {
                fullName: true,
                email: true,
              },
            },
          },
        })
      : []

  const getClerkDisplayName = (clerkUser: any) => {
    const metadata = clerkUser?.publicMetadata as Record<string, unknown> | undefined
    const fullNameFromMetadata = metadata?.fullName || metadata?.full_name || metadata?.name
    
    if (typeof fullNameFromMetadata === "string" && fullNameFromMetadata.trim()) {
      return fullNameFromMetadata.trim()
    }

    const composed = [clerkUser?.firstName?.trim(), clerkUser?.lastName?.trim()]
      .filter(Boolean)
      .join(" ")
      .trim()

    return composed || null
  }

  const client = await clerkClient()
  const creatorClerkIds = Array.from(
    new Set(
      (creators as Array<any>)
        .map((creator) => creator.clerkUserId)
        .filter((value): value is string => typeof value === "string" && value.length > 0)
    )
  )

  const clerkNameById = new Map<string, string>()
  await Promise.all(
    creatorClerkIds.map(async (clerkUserId) => {
      try {
        const clerkUser = await client.users.getUser(clerkUserId)
        const displayName = getClerkDisplayName(clerkUser)
        if (displayName) {
          clerkNameById.set(clerkUserId, displayName)
        }
      } catch {
        // Keep DB value if Clerk lookup fails.
      }
    })
  )

  const creatorById = new Map<string, any>(creators.map((creator: any) => [creator.id, creator]))

  const enrichedLogs = typedLogs.map((log) => {
    const creator = creatorById.get(log.session.createdBy) as any
    const clerkDisplayName =
      typeof creator?.clerkUserId === "string" ? clerkNameById.get(creator.clerkUserId) : undefined
    const fullerName = pickFullerDisplayName(creator?.teacher?.fullName, clerkDisplayName)
    const teacherName = fullerName || creator?.teacher?.email || creator?.email || "Unknown"

    return {
      ...log,
      session: {
        ...log.session,
        teacherName,
      },
    }
  })

  return NextResponse.json({ count: enrichedLogs.length, logs: enrichedLogs })
}

import { prisma } from "@/lib/prisma"
import { auth, clerkClient } from "@clerk/nextjs/server"
import { NextResponse } from "next/server"

async function isAdmin(clerkUserId: string) {
  const actor = await prisma.user.findUnique({
    where: { clerkUserId },
    select: { role: true },
  })

  return actor?.role === "ADMIN"
}

export async function DELETE(
  req: Request,
  { params }: { params: { id: string } }
) {
  const { userId } = await auth()

  if (!userId) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
  }

  if (!(await isAdmin(userId))) {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 })
  }

  const teacherId = params.id

  try {
    const teacher = await prisma.teacher.findUnique({
      where: { id: teacherId },
      select: {
        id: true,
        user: {
          select: {
            id: true,
            clerkUserId: true,
          },
        },
      },
    })

    if (!teacher) {
      return NextResponse.json({ error: "Teacher not found" }, { status: 404 })
    }

    const client = await clerkClient()

    try {
      await client.users.deleteUser(teacher.user.clerkUserId)
    } catch (error) {
      const message = error instanceof Error ? error.message.toLowerCase() : ""
      const shouldIgnore = message.includes("not found") || message.includes("404")

      if (!shouldIgnore) {
        return NextResponse.json(
          { error: "Failed to delete teacher auth account in Clerk" },
          { status: 502 }
        )
      }
    }

    await prisma.$transaction([
      prisma.teacher.delete({ where: { id: teacher.id } }),
      prisma.user.delete({ where: { id: teacher.user.id } }),
    ])

    return NextResponse.json({ message: "Teacher deleted successfully" })
  } catch (error) {
    return NextResponse.json(
      { error: "Failed to delete teacher" },
      { status: 500 }
    )
  }
}

import { prisma } from "@/lib/prisma"
import { auth, clerkClient } from "@clerk/nextjs/server"
import { NextResponse } from "next/server"

async function isAdmin(clerkUserId: string) {
  const actor = await prisma.user.findUnique({
    where: { clerkUserId },
    select: { role: true },
  })

  return actor?.role === "ADMIN"
}

function getNamePartsCount(value: string) {
  return value
    .trim()
    .split(/\s+/)
    .filter(Boolean).length
}

function pickFullerDisplayName(dbName: string | null, clerkName: string | undefined) {
  const normalizedDb = typeof dbName === "string" ? dbName.trim() : ""
  const normalizedClerk = typeof clerkName === "string" ? clerkName.trim() : ""

  if (!normalizedDb && !normalizedClerk) {
    return ""
  }
  if (!normalizedDb) {
    return normalizedClerk
  }
  if (!normalizedClerk) {
    return normalizedDb
  }

  return getNamePartsCount(normalizedDb) >= getNamePartsCount(normalizedClerk)
    ? normalizedDb
    : normalizedClerk
}

export async function GET(req: Request) {
  const { userId } = await auth()

  if (!userId) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
  }

  if (!(await isAdmin(userId))) {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 })
  }

  const url = new URL(req.url)
  const q = url.searchParams.get("q")?.trim().toLowerCase() ?? ""
  const department = url.searchParams.get("department")?.trim() ?? ""

  const teachers = await prisma.teacher.findMany({
    where: {
      ...(department ? { department: { equals: department, mode: "insensitive" } } : {}),
      ...(q
        ? {
            OR: [
              { fullName: { contains: q, mode: "insensitive" } },
              { email: { contains: q, mode: "insensitive" } },
              { user: { email: { contains: q, mode: "insensitive" } } },
            ],
          }
        : {}),
    },
    select: {
      id: true,
      fullName: true,
      email: true,
      department: true,
      userId: true,
      user: {
        select: {
          clerkUserId: true,
          email: true,
        },
      },
    },
    orderBy: [{ department: "asc" }, { fullName: "asc" }],
    take: 500,
  })

  const getClerkDisplayName = (clerkUser: any) => {
    const metadata = clerkUser?.publicMetadata as Record<string, unknown> | undefined
    const fullNameFromMetadata = metadata?.fullName || metadata?.full_name || metadata?.name
    
    if (typeof fullNameFromMetadata === "string" && fullNameFromMetadata.trim()) {
      return fullNameFromMetadata.trim()
    }

    const composed = [clerkUser?.firstName?.trim(), clerkUser?.lastName?.trim()]
      .filter(Boolean)
      .join(" ")
      .trim()

    return composed || null
  }

  const client = await clerkClient()
  const clerkUserIds = Array.from(new Set(teachers.map((teacher) => teacher.user.clerkUserId).filter(Boolean)))

  const clerkNameById = new Map<string, string>()
  await Promise.all(
    clerkUserIds.map(async (clerkUserId) => {
      try {
        const clerkUser = await client.users.getUser(clerkUserId)
        const displayName = getClerkDisplayName(clerkUser)
        if (displayName) {
          clerkNameById.set(clerkUserId, displayName)
        }
      } catch {
        // Keep DB value if Clerk lookup fails.
      }
    })
  )

  const teachersWithDisplayName = teachers.map((teacher) => ({
    ...teacher,
    fullName: pickFullerDisplayName(
      teacher.fullName,
      clerkNameById.get(teacher.user.clerkUserId)
    ),
  }))

  return NextResponse.json({
    count: teachersWithDisplayName.length,
    teachers: teachersWithDisplayName,
  })
}

import { prisma } from "@/lib/prisma"
import { auth } from "@clerk/nextjs/server"
import { NextResponse } from "next/server"

const attendanceModel = prisma.attendance as any

// Campus geo-fence configuration.
// Set these in your env, e.g.:
// CAMPUS_LATITUDE=12.9716
// CAMPUS_LONGITUDE=77.5946
// GEOFENCE_RADIUS_METERS=40
const CAMPUS_LATITUDE = Number(process.env.CAMPUS_LATITUDE ?? "0")
const CAMPUS_LONGITUDE = Number(process.env.CAMPUS_LONGITUDE ?? "0")
const GEOFENCE_RADIUS_METERS = Number(process.env.GEOFENCE_RADIUS_METERS ?? "150")

function toRadians(value: number) {
  return (value * Math.PI) / 180
}

function distanceInMeters(lat1: number, lon1: number, lat2: number, lon2: number): number {
  const R = 6371_000 // metres
  const ╧å1 = toRadians(lat1)
  const ╧å2 = toRadians(lat2)
  const ╬ö╧å = toRadians(lat2 - lat1)
  const ╬ö╬╗ = toRadians(lon2 - lon1)

  const a =
    Math.sin(╬ö╧å / 2) * Math.sin(╬ö╧å / 2) +
    Math.cos(╧å1) * Math.cos(╧å2) *
      Math.sin(╬ö╬╗ / 2) * Math.sin(╬ö╬╗ / 2)

  const c = 2 * Math.atan2(Math.sqrt(a), Math.sqrt(1 - a))

  return R * c
}

export async function POST(req: Request) {
  const { userId } = await auth()

  if (!userId) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
  }

  const actor = await prisma.user.findUnique({
    where: { clerkUserId: userId },
    select: {
      id: true,
      role: true,
    },
  })

  if (actor?.role !== "STUDENT") {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 })
  }

  const student = await prisma.student.findUnique({
    where: { userId: actor.id },
    select: {
      id: true,
      fullName: true,
      isActive: true,
      department: true,
      year: true,
    },
  })

  if (!student || !student.isActive) {
    return NextResponse.json(
      {
        error:
          "Your account is restricted. You cannot make attendance right now. Please contact your dean to reactivate your account.",
        errorCode: "ACCOUNT_RESTRICTED",
      },
      { status: 403 }
    )
  }

  const body = (await req.json()) as {
    sessionId?: string
    latitude?: number
    longitude?: number
  }

  const sessionId = String(body.sessionId ?? "").trim()
  const latitude = typeof body.latitude === "number" ? body.latitude : 0
  const longitude = typeof body.longitude === "number" ? body.longitude : 0

  if (!sessionId) {
    return NextResponse.json({ error: "sessionId is required" }, { status: 400 })
  }

  const session = await prisma.session.findUnique({
    where: { id: sessionId },
    select: {
      id: true,
      department: true,
      year: true,
      expiresAt: true,
    },
  })

  if (!session) {
    return NextResponse.json({ error: "Session not found" }, { status: 404 })
  }

  if (session.expiresAt.getTime() <= Date.now()) {
    return NextResponse.json({ error: "Session expired" }, { status: 410 })
  }

  if (session.department !== student.department || session.year !== student.year) {
    return NextResponse.json({ error: "Session not valid for this student" }, { status: 403 })
  }

  // Geo-fence: require valid coordinates and ensure student is near campus
  const hasCampusCoordinates = CAMPUS_LATITUDE !== 0 && CAMPUS_LONGITUDE !== 0

  if (hasCampusCoordinates) {
    if (!latitude || !longitude) {
      return NextResponse.json(
        {
          error:
            "Location access is required to mark attendance. Please enable location and try again.",
          errorCode: "LOCATION_REQUIRED",
        },
        { status: 400 }
      )
    }

    const distance = distanceInMeters(latitude, longitude, CAMPUS_LATITUDE, CAMPUS_LONGITUDE)

    if (distance > GEOFENCE_RADIUS_METERS) {
      const remaining = Math.max(0, distance - GEOFENCE_RADIUS_METERS)
      return NextResponse.json(
        {
          error:
            "You appear to be outside the college campus. Attendance can only be marked from within campus.",
          errorCode: "GEOFENCE_VIOLATION",
          distanceMeters: Math.round(distance),
          radiusMeters: Math.round(GEOFENCE_RADIUS_METERS),
          remainingMeters: Math.round(remaining),
        },
        { status: 403 }
      )
    }
  }

  const existing = await attendanceModel.findUnique({
    where: {
      sessionId_studentId: {
        sessionId: session.id,
        studentId: student.id,
      },
    },
    select: { id: true },
  })

  if (existing) {
    return NextResponse.json({ error: "Attendance already marked" }, { status: 409 })
  }

  const ipAddress =
    req.headers.get("x-forwarded-for")?.split(",")[0]?.trim() ??
    req.headers.get("x-real-ip") ??
    null

  const userAgent = req.headers.get("user-agent")

  await attendanceModel.create({
    data: {
      sessionId: session.id,
      studentId: student.id,
      status: "PRESENT",
      latitude,
      longitude,
      ipAddress,
      userAgent,
    },
  })

  return NextResponse.json({
    success: true,
    message: "Attendance marked",
  })
}

import { prisma } from "@/lib/prisma"
import { auth } from "@clerk/nextjs/server"
import { NextResponse } from "next/server"

const attendanceModel = prisma.attendance as any

export async function GET(req: Request) {
  const { userId } = await auth()

  if (!userId) {
    return NextResponse.json({ error: "Unauthorized" }, { status: 401 })
  }

  const actor = await prisma.user.findUnique({
    where: { clerkUserId: userId },
    select: {
      id: true,
      role: true,
    },
  })

  if (actor?.role !== "TEACHER") {
    return NextResponse.json({ error: "Forbidden" }, { status: 403 })
  }

  const url = new URL(req.url)
  const sessionId = url.searchParams.get("sessionId")?.trim()

  if (!sessionId) {
    return NextResponse.json({ error: "sessionId is required" }, { status: 400 })
  }

  const session = await prisma.session.findFirst({
    where: {
      id: sessionId,
      createdBy: actor.id,
    },
    select: {
      id: true,
      subject: true,
      department: true,
      year: true,
      expiresAt: true,
      createdAt: true,
    },
  })

  if (!session) {
    return NextResponse.json({ error: "Session not found" }, { status: 404 })
  }

  const [presentCount, totalStudents, attendees] = await Promise.all([
    attendanceModel.count({
      where: {
        sessionId: session.id,
        status: "PRESENT",
      },
    }),
    prisma.student.count({
      where: {
        department: session.department,
        year: session.year,
        isActive: true,
      },
    }),
    attendanceModel.findMany({
      where: {
        sessionId: session.id,
        status: "PRESENT",
      },
      orderBy: {
        createdAt: "desc",
      },
      take: 100,
      select: {
        id: true,
        createdAt: true,
        student: {
          select: {
            fullName: true,
            rollNo: true,
            email: true,
          },
        },
      },
    }),
  ])

  return NextResponse.json({
    session,
    presentCount,
    totalStudents,
    attendees,
    isExpired: session.expiresAt.getTime() <= Date.now(),
  })
}

"use client"

import { Button } from "@/components/ui/button"
import { useRouter } from "next/navigation"
import { useEffect, useRef, useState } from "react"
import { toast } from "sonner"

export default function ScanAttendanceClient({ sessionId }: { sessionId: string }) {
  const router = useRouter()
  const [loading, setLoading] = useState(false)
  const [isRestricted, setIsRestricted] = useState(false)
  const [errorMessage, setErrorMessage] = useState<string | null>(null)
  const autoAttemptedRef = useRef(false)

  const markAttendance = async () => {
    setLoading(true)

    const payload: { sessionId: string; latitude?: number; longitude?: number } = { sessionId }

    if (typeof navigator !== "undefined" && "geolocation" in navigator) {
      await new Promise<void>((resolve) => {
        navigator.geolocation.getCurrentPosition(
          (position) => {
            payload.latitude = position.coords.latitude
            payload.longitude = position.coords.longitude
            resolve()
          },
          () => resolve(),
          {
            enableHighAccuracy: true,
            timeout: 10000,
            maximumAge: 0,
          }
        )
      })
    }

    const res = await fetch("/api/student/attendance", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(payload),
    })

    const data = (await res.json()) as {
      success?: boolean
      message?: string
      error?: string
      errorCode?: string
      distanceMeters?: number
    }

    if (!res.ok) {
      setLoading(false)
      setIsRestricted(data.errorCode === "ACCOUNT_RESTRICTED")

      if (data.errorCode === "ACCOUNT_RESTRICTED") {
        const msg = "Your account is restricted. Please contact your dean to reactivate it."
        setErrorMessage(msg)
        toast.error(msg)
        return
      }

      if (data.errorCode === "LOCATION_REQUIRED") {
        const msg =
          "Turn on location services and allow this browser to access your location, then try again from the classroom."
        setErrorMessage(msg)
        toast.error(msg)
        return
      }

      if (data.errorCode === "GEOFENCE_VIOLATION") {
        const distanceText =
          typeof data.distanceMeters === "number" ? `You seem to be about ${data.distanceMeters}m away. ` : ""
        const msg =
          `${distanceText}You must be inside the classroom to mark attendance. Please move closer and try again.`
        setErrorMessage(msg)
        toast.error(msg)
        return
      }

      const generic = data.error ?? "Could not mark attendance"
      setErrorMessage(generic)
      toast.error(generic)
      return
    }

    setIsRestricted(false)
    setErrorMessage(null)
    toast.success(data.message ?? "Attendance marked")

    setTimeout(() => {
      router.push("/student")
    }, 1500)
  }

  useEffect(() => {
    if (autoAttemptedRef.current) {
      return
    }

    autoAttemptedRef.current = true
    void markAttendance()
  }, [sessionId])

  return (
    <div
      className={`mx-auto max-w-md space-y-4 rounded-2xl border p-6 ${
        isRestricted ? "border-red-300 bg-red-50" : ""
      }`}
    >
      <h1 className="text-2xl font-semibold">Scan Attendance</h1>
      <p className="text-sm text-muted-foreground break-all">Session: {sessionId}</p>

      {loading ? <p className="text-sm">Marking attendance...</p> : null}
      {errorMessage && !loading ? (
        <p className="text-xs text-red-700">{errorMessage}</p>
      ) : null}

      <Button
        type="button"
        onClick={markAttendance}
        disabled={loading || isRestricted}
      >
        {loading ? "Please wait..." : "Mark Attendance"}
      </Button>
    </div>
  )
}

"use client"

import { Button } from "@/components/ui/button"
import { Copy, Download } from "lucide-react"
import { useRouter, useSearchParams } from "next/navigation"
import { useCallback, useEffect, useMemo, useState } from "react"
import { toast } from "sonner"

type SessionData = {
  id: string
  subject: string
  department: string
  year: number
  expiresAt: string
  createdAt: string
}

type SummaryAttendee = {
  id: string
  createdAt: string
  student: {
    fullName: string
    rollNo: number
    email: string | null
  }
}

type SummaryResponse = {
  session: SessionData
  presentCount: number
  totalStudents: number
  attendees: SummaryAttendee[]
  isExpired: boolean
  error?: string
}

export default function TeacherAttendanceLiveClient() {
  const router = useRouter()
  const searchParams = useSearchParams()
  const sessionId = searchParams.get("sessionId")?.trim() ?? ""

  const [summary, setSummary] = useState<SummaryResponse | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)
  const [secondsLeft, setSecondsLeft] = useState(0)
  const [timerReady, setTimerReady] = useState(false)
  const [redirecting, setRedirecting] = useState(false)
  const [endingSession, setEndingSession] = useState(false)

  const scanUrl = useMemo(() => {
    if (!sessionId || typeof window === "undefined") {
      return ""
    }

    return `${window.location.origin}/scan?sessionId=${encodeURIComponent(sessionId)}`
  }, [sessionId])

  const qrImageUrl = useMemo(() => {
    if (!scanUrl) {
      return ""
    }

    return `https://api.qrserver.com/v1/create-qr-code/?size=360x360&data=${encodeURIComponent(scanUrl)}`
  }, [scanUrl])

  const syncSummary = useCallback(async () => {
    if (!sessionId) {
      setLoading(false)
      setError("Missing session id")
      return
    }

    try {
      const res = await fetch(`/api/teacher/attendance/summary?sessionId=${encodeURIComponent(sessionId)}`, {
        cache: "no-store",
      })
      const data = (await res.json()) as SummaryResponse

      if (!res.ok) {
        setError(data.error ?? "Failed to load session")
        setSummary(null)
        return
      }

      setSummary(data)
      setError(null)
    } catch {
      setError("Failed to load session")
      setSummary(null)
    } finally {
      setLoading(false)
    }
  }, [sessionId])

  useEffect(() => {
    void syncSummary()

    const poller = window.setInterval(() => {
      void syncSummary()
    }, 3000)

    return () => {
      window.clearInterval(poller)
    }
  }, [syncSummary])

  useEffect(() => {
    if (!summary) {
      setTimerReady(false)
      return
    }

    const tick = () => {
      const diff = Math.max(0, Math.floor((new Date(summary.session.expiresAt).getTime() - Date.now()) / 1000))
      setSecondsLeft(diff)
      setTimerReady(true)
    }

    tick()
    const timer = window.setInterval(tick, 1000)

    return () => {
      window.clearInterval(timer)
    }
  }, [summary])

  useEffect(() => {
    if (!summary || redirecting || !timerReady) {
      return
    }

    if (secondsLeft > 0 && !summary.isExpired) {
      return
    }

    setRedirecting(true)
    router.replace("/teacher/dashboard")
  }, [secondsLeft, summary, redirecting, router, timerReady])

  const copyScanUrl = async () => {
    if (!scanUrl) return

    try {
      await navigator.clipboard.writeText(scanUrl)
      toast.success("Scan link copied")
    } catch {
      toast.error("Unable to copy link")
    }
  }

  const downloadQr = async () => {
    if (!qrImageUrl) return

    try {
      const res = await fetch(qrImageUrl)
      const blob = await res.blob()
      const url = URL.createObjectURL(blob)
      const link = document.createElement("a")
      link.href = url
      link.download = `attendance-qr-${sessionId}.png`
      document.body.appendChild(link)
      link.click()
      document.body.removeChild(link)
      URL.revokeObjectURL(url)
      toast.success("QR downloaded")
    } catch {
      window.open(qrImageUrl, "_blank", "noopener,noreferrer")
    }
  }

  const manuallyEndSession = async () => {
    if (!summary || endingSession) {
      return
    }

    setEndingSession(true)

    try {
      const res = await fetch("/api/teacher/attendance/session/end", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({ sessionId: summary.session.id }),
      })

      const data = (await res.json()) as { ended?: boolean; error?: string }

      if (!res.ok || !data.ended) {
        toast.error(data.error ?? "Failed to end session")
        return
      }

      toast.success("Session ended")
      router.replace("/teacher/dashboard")
    } catch {
      toast.error("Failed to end session")
    } finally {
      setEndingSession(false)
    }
  }

  const canManuallyEnd = !!summary && !summary.isExpired && secondsLeft > 0

  return (
    <section className="relative h-screen overflow-hidden bg-white px-4 py-3 md:px-6 md:py-4">
      <div aria-hidden="true" className="pointer-events-none absolute -left-[130px] -top-[120px] h-[620px] w-[620px]">
        <div className="absolute left-0 top-0 h-[417px] w-[417px] rounded-full bg-[#b7e7ff]/70 blur-[55px]" />
        <div className="absolute left-[120px] top-[58px] h-[417px] w-[417px] rounded-full bg-white blur-[65px]" />
      </div>
      <div aria-hidden="true" className="pointer-events-none absolute -bottom-[170px] -right-[140px] h-[640px] w-[640px]">
        <div className="absolute bottom-0 right-0 h-[440px] w-[440px] rounded-full bg-[#839aff]/78 blur-[75px]" />
        <div className="absolute bottom-[126px] right-[150px] h-[420px] w-[420px] rounded-full bg-white blur-[80px]" />
      </div>

      <div className="relative z-10 mx-auto flex h-full max-w-[1400px] min-h-0 flex-col gap-4">
        <h1 className="shrink-0 text-center font-[var(--font-lora)] text-[34px] leading-tight tracking-[-0.8px] text-[#40444b] md:text-[44px]">
          Scan The Qr Code & Mark Your Attendance
        </h1>

        {loading ? (
          <div className="rounded-[18px] border border-[#dedede] bg-white/80 p-8 text-center text-[#5f636a]">Loading session...</div>
        ) : error || !summary ? (
          <div className="space-y-4 rounded-[18px] border border-rose-200 bg-rose-50 p-8 text-center">
            <p className="text-rose-700">{error ?? "Session not found"}</p>
            <Button
              type="button"
              onClick={() => router.replace("/teacher/dashboard")}
              className="h-[44px] rounded-full border border-[#1e1f24] bg-[linear-gradient(180deg,#1e2027_0%,#14161b_100%)] px-5 text-[15px] font-semibold tracking-[-0.3px] text-white"
            >
              Back to Dashboard
            </Button>
          </div>
        ) : (
          <div className="min-h-0 flex-1 space-y-4 overflow-hidden">
            <div className="grid shrink-0 grid-cols-1 gap-4 lg:grid-cols-[320px_minmax(0,1fr)] lg:items-center">
              <div className="space-y-2">
                <p className="text-[22px] leading-[1.2] tracking-[-0.3px] text-[#22262d] md:text-[24px]">
                  <span className="font-semibold">Session:</span>{" "}
                  <span className="font-normal">{summary.session.subject} | {summary.session.department} | Year {summary.session.year}</span>
                </p>
                <p className="text-[22px] leading-[1.2] tracking-[-0.3px] text-[#22262d] md:text-[24px]">
                  <span className="font-semibold">Status:</span>{" "}
                  <span className="font-normal">Active </span>
                  <span className="text-[#2285da]">({secondsLeft} Seconds Left)</span>
                </p>
                <p className="text-[22px] leading-[1.2] tracking-[-0.3px] text-[#22262d] md:text-[24px]">
                  <span className="font-semibold">Present:</span>{" "}
                  <span className="text-[#2285da]">{summary.presentCount}/{summary.totalStudents}</span>
                </p>
                <Button
                  type="button"
                  onClick={manuallyEndSession}
                  disabled={!canManuallyEnd || endingSession}
                  className="h-10 rounded-full border border-[#2c2f35] bg-[linear-gradient(180deg,#3a3d43_0%,#24272d_100%)] px-4 text-[13px] font-semibold text-white"
                >
                  {endingSession ? "Ending..." : "End Session"}
                </Button>
              </div>

              <div className="mx-auto flex w-full max-w-[560px] flex-col items-center gap-3">
                <div className="rounded-[4px] border-[6px] border-[#ececec] bg-white p-2">
                  {qrImageUrl ? <img src={qrImageUrl} alt="Attendance QR" className="h-[180px] w-[180px]" /> : null}
                </div>

                <div className="flex h-[64px] w-full items-center gap-2 rounded-[14px] border-[4px] border-[#d5eeff] bg-[#bfe5ff] px-3">
                  <p className="min-w-0 flex-1 truncate text-[14px] tracking-[-0.2px] text-[#4b5360]">{scanUrl}</p>
                  <div className="flex items-center gap-2">
                    <Button
                      type="button"
                      onClick={copyScanUrl}
                      className="h-9 rounded-full border border-[#2c2f35] bg-[linear-gradient(180deg,#3a3d43_0%,#24272d_100%)] px-3 text-[12px] font-medium text-white"
                    >
                      <Copy className="mr-1 h-3.5 w-3.5" />
                      Copy
                    </Button>
                    <Button
                      type="button"
                      onClick={downloadQr}
                      className="h-9 rounded-full border border-[#2c2f35] bg-[linear-gradient(180deg,#3a3d43_0%,#24272d_100%)] px-3 text-[12px] font-medium text-white"
                    >
                      <Download className="mr-1 h-3.5 w-3.5" />
                      Download
                    </Button>
                  </div>
                </div>
              </div>
            </div>

            <div className="min-h-0 flex-1 rounded-[18px] border border-[#d7d7d7] bg-white/95 p-3">
              <div className="h-full overflow-auto">
                <table className="w-full min-w-[820px] border-separate border-spacing-y-1.5">
                  <thead>
                    <tr className="text-left text-[14px] font-semibold tracking-[-0.2px] text-[#202228]">
                      <th className="px-3 py-1">Student</th>
                      <th className="px-3 py-1">Roll</th>
                      <th className="px-3 py-1">Marked At</th>
                      <th className="px-3 py-1">Email</th>
                    </tr>
                  </thead>
                  <tbody className="text-[14px] tracking-[-0.1px] text-[#30333a]">
                    {summary.attendees.length === 0 ? (
                      <tr>
                        <td colSpan={4} className="rounded-[10px] border border-[#ececec] bg-[#fbfbfb] px-3 py-6 text-center text-[13px] text-[#737373]">
                          No attendance marked yet.
                        </td>
                      </tr>
                    ) : (
                      summary.attendees.map((entry) => (
                        <tr key={entry.id}>
                          <td className="rounded-l-[10px] border border-r-0 border-[#ececec] bg-[#fbfbfb] px-3 py-2">
                            {entry.student.fullName}
                          </td>
                          <td className="border-y border-[#ececec] bg-[#fbfbfb] px-3 py-2">{entry.student.rollNo}</td>
                          <td className="border-y border-[#ececec] bg-[#fbfbfb] px-3 py-2">{formatMarkedAt(entry.createdAt)}</td>
                          <td className="rounded-r-[10px] border border-l-0 border-[#ececec] bg-[#fbfbfb] px-3 py-2">{entry.student.email ?? "-"}</td>
                        </tr>
                      ))
                    )}
                  </tbody>
                </table>
              </div>
            </div>
          </div>
        )}
      </div>
    </section>
  )
}

function formatMarkedAt(value: string) {
  const date = new Date(value)
  if (!Number.isFinite(date.getTime())) {
    return "-"
  }

  return `${date.toLocaleDateString("en-GB", {
    day: "2-digit",
    month: "short",
    year: "numeric",
  })}  ${date.toLocaleTimeString("en-US", {
    hour: "2-digit",
    minute: "2-digit",
    hour12: true,
  })}`
}

"use client"

import { Button } from "@/components/ui/button"
import { DropdownSelect } from "@/components/ui/dropdown-select"
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog"
import { useEffect, useMemo, useState } from "react"
import { toast } from "sonner"
import { Search } from "lucide-react"

const DEPARTMENTS = ["BBA", "BCA"]

type StudentRow = {
  id: string
  fullName: string
  email: string | null
  department: string
  year: number
  rollNo: number
  isActive: boolean
  academicYear: string
}

type StudentsResponse = {
  count: number
  department: string
  students: StudentRow[]
  error?: string
}

type AtRiskStudent = {
  id: string
  fullName: string
  email: string | null
  rollNo: number
  attendancePercentage: number
  present: number
  totalConsidered: number
}

type AtRiskResponse = {
  department: string
  year: number
  threshold: number
  totalStudents: number
  totalSessions: number
  atRiskCount: number
  recipientCount: number
  atRiskStudents: AtRiskStudent[]
  mailtoUrl: string | null
  error?: string
}

export default function TeacherStudentsTable() {
  const [students, setStudents] = useState<StudentRow[]>([])
  const [departmentLabel, setDepartmentLabel] = useState("")
  const [department, setDepartment] = useState("all")
  const [query, setQuery] = useState("")
  const [year, setYear] = useState("all")
  const [loading, setLoading] = useState(false)
  const [warningOpen, setWarningOpen] = useState(false)
  const [warningDepartment, setWarningDepartment] = useState("BCA")
  const [warningYear, setWarningYear] = useState("1")
  const [warningLoading, setWarningLoading] = useState(false)
  const [warningSending, setWarningSending] = useState(false)
  const [warningResult, setWarningResult] = useState<AtRiskResponse | null>(null)

  const fetchStudents = async () => {
    setLoading(true)

    const url = new URL("/api/teacher/students", window.location.origin)
    if (department.trim()) {
      url.searchParams.set("department", department.trim())
    }
    if (query.trim()) {
      url.searchParams.set("q", query.trim())
    }
    if (year.trim() && year !== "all") {
      url.searchParams.set("year", year.trim())
    }

    const res = await fetch(url.toString(), { method: "GET" })
    const data = (await res.json()) as StudentsResponse

    if (!res.ok) {
      setStudents([])
      toast.error(data.error ?? "Failed to fetch students")
      setLoading(false)
      return
    }

    setStudents(data.students)
    setDepartmentLabel(data.department)

    if (data.department && DEPARTMENTS.includes(data.department) && warningDepartment !== data.department) {
      setWarningDepartment(data.department)
    }

    setLoading(false)
  }

  useEffect(() => {
    void fetchStudents()
  }, [department])

  const prepareLowAttendanceWarnings = async () => {
    if (!warningDepartment || !warningYear) {
      toast.error("Please choose department and year")
      return
    }

    setWarningLoading(true)

    try {
      const res = await fetch("/api/teacher/students/at-risk-email", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          department: warningDepartment,
          year: Number(warningYear),
          threshold: 75,
        }),
      })

      const data = (await res.json()) as AtRiskResponse
      setWarningResult(data)

      if (!res.ok) {
        toast.error(data.error ?? "Failed to build warning email list")
        return
      }

      if (data.totalStudents === 0) {
        toast.info(`No students found in ${data.department} Year ${data.year}`)
        return
      }

      if (data.atRiskCount === 0) {
        toast.info(`No students below 75% in ${data.department} Year ${data.year}`)
        return
      }

      toast.success(`Found ${data.atRiskCount} students below 75%`) 
    } catch {
      toast.error("Failed to build warning email list")
    } finally {
      setWarningLoading(false)
    }
  }

  const downloadCSV = () => {
    if (!warningResult || warningResult.atRiskStudents.length === 0) {
      toast.error("No students to download")
      return
    }

    const headers = ["Student Name", "Roll No", "Email", "Attendance %"]
    const rows = warningResult.atRiskStudents.map((student) => [
      student.fullName,
      student.rollNo.toString(),
      student.email || "",
      `${student.attendancePercentage}%`,
    ])

    const csv = [headers, ...rows]
      .map((row) =>
        row
          .map((cell) => {
            const cellStr = String(cell)
            return cellStr.includes(",") || cellStr.includes('"') ? `"${cellStr.replace(/"/g, '""')}"` : cellStr
          })
          .join(",")
      )
      .join("\n")

    const blob = new Blob([csv], { type: "text/csv" })
    const url = URL.createObjectURL(blob)
    const a = document.createElement("a")
    a.href = url
    a.download = `below-75-${warningDepartment}-year${warningYear}-${new Date().toISOString().split("T")[0]}.csv`
    document.body.appendChild(a)
    a.click()
    document.body.removeChild(a)
    URL.revokeObjectURL(url)

    toast.success("CSV downloaded!")
  }

  const sendWarningEmail = async () => {
    if (!warningResult || warningResult.atRiskStudents.length === 0) {
      toast.error("No students to email")
      return
    }

    setWarningSending(true)

    try {
      const res = await fetch("/api/teacher/students/send-attendance-warning", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify({
          department: warningDepartment,
          year: Number(warningYear),
          atRiskStudents: warningResult.atRiskStudents,
        }),
      })

      const data = (await res.json()) as { sent?: number; failed?: number; error?: string }

      if (!res.ok) {
        toast.error(data.error ?? "Failed to send emails")
        return
      }

      toast.success(`Sent ${data.sent ?? 0} warning emails`)
      setWarningOpen(false)
      setWarningResult(null)
    } catch {
      toast.error("Failed to send emails")
    } finally {
      setWarningSending(false)
    }
  }

  const subtitle = useMemo(() => {
    if (!departmentLabel) {
      return ""
    }
    return `${departmentLabel} department`
  }, [departmentLabel])

  return (
    <div className="space-y-4">
      <div className="flex items-end justify-between gap-3">
        <div className="min-w-0 flex-1 overflow-x-auto pb-1">
          <div className="flex min-w-max items-center gap-[10px]">
            <label className="flex h-[43px] w-[320px] items-center gap-[9px] rounded-[10px] border-[0.4px] border-[#afafaf] bg-[#f9f9f9] px-[9px] py-[3px]">
              <Search className="h-5 w-5 text-[#606060]" strokeWidth={1.8} />
              <input
                value={query}
                onChange={(event) => setQuery(event.target.value)}
                placeholder="Search name, email, roll no"
                aria-label="Search students"
                disabled={loading}
                className="w-full bg-transparent text-[14px] tracking-[-0.2px] text-[#3a3a3a] outline-none placeholder:text-[#8a8a8a]"
              />
            </label>

            <div className="h-[40px] min-w-[182px] shrink-0">
              <DropdownSelect
                value={department}
                onValueChange={setDepartment}
                disabled={loading}
                options={[
                  { value: "all", label: "All Departments" },
                  ...DEPARTMENTS.map((option) => ({ value: option, label: option })),
                ]}
                triggerClassName="h-full min-w-[182px] rounded-[10px] border-[0.5px] border-[#c0c0c0] bg-white px-3 text-[14px] tracking-[-0.28px] text-[#3d3d3d]"
                chevronClassName="h-[15px] w-[15px] text-[#767676]"
                ariaLabel="Filter by department"
              />
            </div>

            <div className="h-[40px] min-w-[138px] shrink-0">
              <DropdownSelect
                value={year}
                onValueChange={setYear}
                disabled={loading}
                options={[
                  { value: "all", label: "All Years" },
                  { value: "1", label: "Year 1" },
                  { value: "2", label: "Year 2" },
                  { value: "3", label: "Year 3" },
                ]}
                triggerClassName="h-full min-w-[138px] rounded-[10px] border-[0.5px] border-[#c0c0c0] bg-white px-3 text-[14px] tracking-[-0.28px] text-[#3d3d3d]"
                chevronClassName="h-[15px] w-[15px] text-[#767676]"
                ariaLabel="Filter by year"
              />
            </div>
          </div>
        </div>

        <div className="flex shrink-0 items-center gap-[10px]">
          <Button
            type="button"
            onClick={fetchStudents}
            disabled={loading}
            className="h-[43px] rounded-[10px] border border-[#1e1f24] bg-[linear-gradient(180deg,#1e2027_0%,#14161b_100%)] px-4 text-[14px] font-semibold text-white"
          >
            {loading ? "Searching..." : "Search"}
          </Button>
          <Button
            type="button"
            variant="outline"
            onClick={() => {
              setWarningResult(null)
              setWarningOpen(true)
            }}
            disabled={loading}
            className="h-[43px] rounded-[10px] border-[0.5px] border-[#c0c0c0] bg-white px-4 text-[14px] font-medium text-[#2f2f2f]"
          >
            Email Below 75%
          </Button>
        </div>
      </div>

      {subtitle ? <p className="text-[13px] tracking-[-0.26px] text-[#6d6d6d]">Showing {subtitle}</p> : null}

      <div className="overflow-x-auto">
        <table className="w-full min-w-[920px] border-separate border-spacing-y-[9px]">
          <thead>
            <tr className="text-left text-[15px] font-semibold tracking-[-0.3px] text-black">
              <th className="px-3 py-1">Name</th>
              <th className="px-3 py-1">Email</th>
              <th className="px-3 py-1">Year</th>
              <th className="px-3 py-1">Roll No</th>
              <th className="px-3 py-1">Status</th>
            </tr>
          </thead>
          <tbody className="text-[14px] tracking-[-0.2px] text-[#2a2a2a]">
            {loading ? (
              Array.from({ length: 6 }).map((_, index) => (
                <tr key={`teacher-students-loading-${index}`}>
                  <td className="rounded-l-[10px] border border-r-0 border-[#ececec] bg-[#fbfbfb] px-3 py-[11px]">
                    <div className="h-5 w-32 animate-pulse rounded-full bg-[#ececec]" />
                  </td>
                  <td className="border-y border-[#ececec] bg-[#fbfbfb] px-3 py-[11px]">
                    <div className="h-5 w-44 animate-pulse rounded-full bg-[#ececec]" />
                  </td>
                  <td className="border-y border-[#ececec] bg-[#fbfbfb] px-3 py-[11px]">
                    <div className="h-5 w-16 animate-pulse rounded-full bg-[#ececec]" />
                  </td>
                  <td className="border-y border-[#ececec] bg-[#fbfbfb] px-3 py-[11px]">
                    <div className="h-5 w-16 animate-pulse rounded-full bg-[#ececec]" />
                  </td>
                  <td className="rounded-r-[10px] border border-l-0 border-[#ececec] bg-[#fbfbfb] px-3 py-[11px]">
                    <div className="h-5 w-20 animate-pulse rounded-full bg-[#ececec]" />
                  </td>
                </tr>
              ))
            ) : students.length === 0 ? (
              <tr>
                <td
                  colSpan={5}
                  className="rounded-[10px] border border-[#ececec] bg-[#fbfbfb] px-3 py-8 text-center text-[14px] text-[#737373]"
                >
                  No students found.
                </td>
              </tr>
            ) : (
              students.map((student) => (
                <tr key={student.id}>
                  <td className="rounded-l-[10px] border border-r-0 border-[#ececec] bg-[#fbfbfb] px-3 py-[11px] font-medium text-[#1f1f1f]">
                    {student.fullName}
                  </td>
                  <td className="border-y border-[#ececec] bg-[#fbfbfb] px-3 py-[11px]">{student.email ?? "-"}</td>
                  <td className="border-y border-[#ececec] bg-[#fbfbfb] px-3 py-[11px]">{student.year}</td>
                  <td className="border-y border-[#ececec] bg-[#fbfbfb] px-3 py-[11px]">{student.rollNo}</td>
                  <td className="rounded-r-[10px] border border-l-0 border-[#ececec] bg-[#fbfbfb] px-3 py-[11px]">
                    {student.isActive ? "Active" : "Inactive"}
                  </td>
                </tr>
              ))
            )}
          </tbody>
        </table>
      </div>

      <Dialog open={warningOpen} onOpenChange={setWarningOpen}>
        <DialogContent className="max-w-[560px] rounded-[28px] border border-[#d9d9d9] bg-white p-7 shadow-none ring-0">
          <DialogHeader>
            <DialogTitle className="text-[34px] font-semibold tracking-[-0.8px] text-[#17181b] md:text-[30px]">
              Email Below 75% Warning
            </DialogTitle>
            <DialogDescription className="text-[14px] leading-[1.35] tracking-[-0.2px] text-[#6f6f6f]">
              Select department and year to identify and email students below 75% attendance.
            </DialogDescription>
          </DialogHeader>

          <div className="grid grid-cols-1 gap-3 sm:grid-cols-2">
            <DropdownSelect
              value={warningDepartment}
              onValueChange={setWarningDepartment}
              options={DEPARTMENTS.map((option) => ({ value: option, label: option }))}
              triggerClassName="h-[44px] rounded-full border-[0.5px] border-[#c0c0c0] bg-[#f9f9f9] px-4 text-[15px] tracking-[-0.2px] text-[#2f2f2f]"
              chevronClassName="h-[15px] w-[15px] text-[#767676]"
              ariaLabel="Warning department"
            />

            <DropdownSelect
              value={warningYear}
              onValueChange={setWarningYear}
              options={[
                { value: "1", label: "1st Year" },
                { value: "2", label: "2nd Year" },
                { value: "3", label: "3rd Year" },
              ]}
              triggerClassName="h-[44px] rounded-full border-[0.5px] border-[#c0c0c0] bg-[#f9f9f9] px-4 text-[15px] tracking-[-0.2px] text-[#2f2f2f]"
              chevronClassName="h-[15px] w-[15px] text-[#767676]"
              ariaLabel="Warning year"
            />
          </div>

          {warningResult ? (
            <div className="rounded-[12px] border border-[#d6dce3] bg-[#f8fafc] p-3 text-[12px] tracking-[-0.12px] text-[#4b5563]">
              {warningResult.totalStudents === 0 ? (
                <p className="text-[#687384]">
                  No students found in {warningResult.department} Year {warningResult.year}.
                </p>
              ) : warningResult.atRiskCount === 0 ? (
                <p className="text-[#687384]">
                  No students below 75% in {warningResult.department} Year {warningResult.year}.
                </p>
              ) : (
                <>
                  <p>
                    {warningResult.department} Year {warningResult.year}: {warningResult.atRiskCount} below 75%
                    ({warningResult.recipientCount} with email)
                  </p>
                  <p className="mt-1 text-[#7a8595]">
                    Based on {warningResult.totalSessions} sessions for {warningResult.totalStudents} active students.
                  </p>

                  {warningResult.atRiskStudents.length > 0 ? (
                    <div className="mt-3 max-h-36 overflow-auto rounded-[10px] border border-[#d8dee8] bg-white">
                      <table className="w-full text-left text-xs">
                        <thead className="sticky top-0 bg-[#f0f4f8]">
                          <tr>
                            <th className="px-2 py-1 font-medium">Student</th>
                            <th className="px-2 py-1 font-medium">Roll</th>
                            <th className="px-2 py-1 font-medium">Attendance</th>
                          </tr>
                        </thead>
                        <tbody>
                          {warningResult.atRiskStudents.map((student) => (
                            <tr key={student.id}>
                              <td className="px-2 py-1">{student.fullName}</td>
                              <td className="px-2 py-1">{student.rollNo}</td>
                              <td className="px-2 py-1">{student.attendancePercentage}%</td>
                            </tr>
                          ))}
                        </tbody>
                      </table>
                    </div>
                  ) : null}
                </>
              )}
            </div>
          ) : null}

          <DialogFooter className="flex-wrap gap-2 sm:justify-start">
            <Button
              variant="outline"
              onClick={() => setWarningOpen(false)}
              className="h-[42px] rounded-full border-[0.5px] border-[#c8c8c8] bg-[#f2f2f2] px-5 text-[14px] font-medium text-[#2c2c2c]"
            >
              Cancel
            </Button>
            <Button
              type="button"
              variant="outline"
              onClick={downloadCSV}
              disabled={warningLoading || !warningResult || warningResult.atRiskStudents.length === 0}
              className="h-[42px] rounded-full border-[0.5px] border-[#d0d0d0] bg-[#f5f5f5] px-5 text-[14px] font-medium text-[#6a6a6a] disabled:opacity-70"
            >
              Download CSV
            </Button>
            <Button
              type="button"
              onClick={() => void prepareLowAttendanceWarnings()}
              disabled={warningLoading}
              className="h-[42px] rounded-full border border-[#1e1f24] bg-[linear-gradient(180deg,#1e2027_0%,#14161b_100%)] px-5 text-[14px] font-semibold tracking-[-0.2px] text-white hover:brightness-105"
            >
              {warningLoading ? "Finding..." : "Find Below 75%"}
            </Button>
            <Button
              type="button"
              onClick={() => void sendWarningEmail()}
              disabled={warningSending || !warningResult || warningResult.atRiskStudents.length === 0}
              className="h-[42px] rounded-full border border-[#1e1f24] bg-[linear-gradient(180deg,#1e2027_0%,#14161b_100%)] px-5 text-[14px] font-semibold tracking-[-0.2px] text-white hover:brightness-105 disabled:opacity-60"
            >
              {warningSending ? "Sending..." : "Send Email"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  )
}

